"""Surgical rev3 to rev4 manuscript correction from November 2026 audit outputs."""
from pathlib import Path
import sys

from docx import Document
from docx.shared import Inches, Pt

SOURCE = Path("Auto-SqPCA_MethodsX_manuscript_rev3_audit.docx")
TARGET = Path("Auto-SqPCA_MethodsX_manuscript_rev4_audit_candidate.docx")
FIGURE = Path(__file__).resolve().parent / "ablation_risk_coverage.png"
if len(sys.argv) >= 3:
    SOURCE, TARGET = map(Path, sys.argv[1:3])
    if len(sys.argv) >= 4: FIGURE = Path(sys.argv[3])

doc = Document(SOURCE)
p = doc.paragraphs


def replace(index: int, text: str, run: int = 0) -> None:
    p[index].runs[run].text = text


replace(16, "Principal component analysis (PCA) can extract the solar quiet (Sq) daily variation from geomagnetic records, but the published method was demonstrated at one mid-latitude observatory without an evaluated gap procedure. Auto-SqPCA adapts its correlation and surrogate selection rule with local-time matrices, iterative rank-3 SVD gap filling, a parsimony rule, day-bootstrap diagnostics and explicit abstention. An independent re-implementation agreed structurally with published PC1 modes (|r| ≥ 0.9993 in 381 matrices), but only 56 met the pre-specified 1% numerical tolerance. At 5–10% missingness, gap filling showed no advantage over interpolation for random gaps; for block gaps it lowered median error but raised tail error and depended on the iteration cap. Component sums showed no demonstrated advantage. The frozen held-out benchmark accepted 2,083/2,808 unmasked cases (74.2%), below the 80% target. A post-hoc matched-acceptance comparison found no clear advantage of stability-based rejection over correlation ranking; both had lower error than random rejection in this benchmark. In a paired synthetic null, candidate pass and full acceptance were 57/100 and 16/100 with an in-matrix IQD reference, and 41/100 and 13/100 with an independent reference. At eight observatories, 830/1,068 component-months were accepted. Agreement with DIFI-8 is reference-model agreement, not independent validation of Sq accuracy.")
replace(28, "Auto-SqPCA processes one observatory, one component (X, Y or Z) and one calendar month at a time. Table 1 separates what is inherited from the original method from what is modified or added, with the evidence available for each change. Frozen Phase 3 results were generated by the archived code; the portable version 1.0.1rc1 package vendors byte-identical numerical cores and adds explicit input guards. Valid finite-input output matched the frozen code exactly in targeted tests. Parameter values below are those frozen for validation unless labelled post hoc.")
replace(38, "A month is processed only if its observed fraction, counted before filling over the 24 × N component grid, is at least 0.90 and every local day has at least 6 finite hours; otherwise it returns no curve. The 6-hour condition preserves the fixed GFZ day indices in this implementation; it is not a mathematical requirement of SVD. Remaining gaps are filled by iterative rank-3 SVD imputation. Missing entries begin at their observed daily mean. On every iteration the current mean of each filled day is recalculated, subtracted, and added back after rank-3 reconstruction; only missing entries are replaced, leaving observations unchanged. A complete finite matrix is returned unchanged with zero iterations. The portable release converts NaN and infinity to missing before initialization; the historical finite-input analysis code is unchanged. Iteration stops when the largest change of a filled entry is below 10⁻⁸ nT or after 500 iterations. The stored iteration count and final change distinguish tolerance stopping from cap stopping; a capped result is not labelled converged. This is iterative EOF-based filling [4,5] on monthly matrices.")
replace(86, " The component experiment omits the completeness and stability rules. To see whether its differences reach the delivered output, the frozen workflow (completeness rules, gap filling, selection, 200 bootstrap resamples, A1–A3) was run with imputation and with linear interpolation on the same held-out masked cases (2,100 per gap setting: 420 eligible month–component pairs × the first 5 of 20 mask replicates), with identical bootstrap seeds (Table 6). Original gaps were filled before synthetic masks were generated. At a nominal 10% random mask, stochastic realized missing fractions sometimes exceeded 10%, causing A3 when the observed fraction fell below 0.90; original gaps did not add to the synthetic mask fraction. For random hours, acceptance was nearly identical with the two methods, and among cases accepted with both, imputation had a slightly larger error. For 6-h and 24-h blocks, few cases were accepted (13.7% and 3.6%); among those accepted with both methods, imputation had a smaller error. No case with 72-h blocks or whole missing days was accepted, because each such month contained a day with fewer than 6 valid hours. In the delivered output, the gap-filling step therefore makes little difference for scattered gaps, slightly in favour of interpolation, and helps only in the few block-gap months that pass the completeness rules.", 1)
replace(100, " On held-out unmasked cases, component sums with parsimony showed no demonstrated error advantage over the single best-correlated component (median paired difference 0.000; 95% CI 0.000–0.000). This aggregate median does not imply identical outcomes in every case. The frozen rule accepted 2,083/2,808 cases (74.18%), below the pre-specified 80% target. Accepted cases had median relative L2 error 0.046 and 90th-percentile error 0.215. All 2,808 held-out 20%-masked cases failed completeness. With α = 0, 107/312 cases (34.3%) were accepted, but the residual carries real Sq variability, so this is not a pure-null false-positive estimate.", 1)
replace(101, " For 2,083 accepted held-out unmasked cases, the frozen 5th–95th percentile bands were recomputed after checking 20 cases against archived candidate and stability values. Mean pointwise coverage of the hourly target α·Sq_target was 95.9% over accepted cases: 88%, 97% and 99% for α = 0.5, 1 and 2, respectively. At least 22 of 24 target hours lay in the band for 301/440 cases at α = 0.5 (68.4%; station-month cluster 95% CI 61.8–74.4%), 678/746 at α = 1 (90.9%; 87.9–93.9%), and 867/897 at α = 2 (96.7%; 94.9–98.2%). These are descriptive fractions of hours, not simultaneous-curve coverage or confidence-interval calibration. The band is conditional on the filled matrix and IQD reference.", 1)
replace(110, "Table 9. Results by station and component: abstention, and for accepted cases the median correlation with DIFI-8, the median ratio of peak-to-peak amplitude (extracted / model), and the median root-mean-square difference (RMSE, post hoc). Model amplitude is the median across all cases at that station and component.")
replace(120, " In the archived exploratory tests, at least one candidate passed in 225/400 autocorrelated null months with an in-matrix reference and 177/400 with an independent reference. In a separate 60-month bank, 7/60 passed the full A1+A2 workflow; these banks cannot be paired. A new post-hoc shared bank used 100 null matrices per reference design (AR(1) hourly dependence 0.9, 30 days, marginal noise SD 5 nT), the frozen seven-candidate rule, 1,000 surrogates and 200 day bootstraps. With in-matrix reference, 57/100 passed A1 and 16/100 passed A1+A2 (41 paired pass-to-reject transitions); with independent reference, 41/100 passed A1 and 13/100 passed A1+A2 (28 transitions). Wilson 95% intervals for full acceptance were 10.1–24.4% and 7.8–21.0%, respectively. These results apply only to the specified synthetic null and do not establish workflow-level false-positive control.", 2)
replace(126, "•  The per-candidate surrogate test provides no established workflow-level false-positive control, shares reference days with the matrix and tests seven candidates without family-wise correction; using |r| can accept opposite polarity. In a new paired null, stability rejection reduced acceptance within both tested reference constructions, but full acceptance remained 16/100 and 13/100, respectively, under this synthetic design.")
replace(127, "•  Abstention missed the 80% acceptance criterion (74.2%). At matched acceptance, the post-hoc stability ranking and a holdout-derived correlation ranking had nearly identical errors, with cluster intervals for their paired differences spanning zero. The correlation cutoff was selected on the holdout for descriptive comparison and is not validated for deployment. The band is conditional on filling and reference construction; weak-signal mean pointwise coverage was 88% in the benchmark, without a simultaneous-coverage guarantee.")
replace(129, "•  Masking errors are relative to a linearly completed unmasked-month output; the semi-synthetic target and application comparator are DIFI-8 curves, not observed true Sq. DIFI-8 includes an induced component and uses selected ground observatory data, but membership of these eight stations in its model-building set could not be verified from the available records. Local induction not represented by the model may remain. Nineteen January 2014 UTC samples fell outside its recommended time range. Removing them in a post-hoc sensitivity check changed the two affected monthly target curves by at most 0.093 nT at any hour, and five accepted E3 correlations by at most 0.00037; this does not test other DIFI uncertainties.")
replace(132, "•  Internal plans were not externally registered. Tables 5–7, RMSE, band coverage, ablation, paired null and DIFI sensitivity are post hoc. A full clean raw-data rerun remains undocumented; one GUA month was reproduced from its WDC ZIP through 54 E2 cases.")
p[140].clear()
p[140].add_run("Declaration of generative AI and AI-assisted technologies in the writing process.").bold = True
p[140].add_run(" During the preparation of this work the authors used Claude (Anthropic) and Codex (OpenAI) to assist with analysis planning, code development, and drafting and editing of the manuscript. The authors are responsible for the accuracy and integrity of the final content.")
replace(144, "Analysis plans, deviation logs, case manifests, per-case results, post-hoc audit scripts and outputs, environment versions, and figure/table source data are available in the Auto-SqPCA GitHub repository. The historical results correspond to commit 2dadbbd; the audited portable package and additional analyses are version 1.0.1rc1, pending a reviewed release. Raw third-party records remain subject to provider access terms; repository manifests record source URLs and checksums. A GUA January 2014 slice from authenticated WDC hourly data through residual construction and 54 E2 cases matched archived outputs, but a complete end-to-end clean-environment rerun from all third-party raw data remains undocumented.")

# Table 1 scientific benefit statements and Table 6 rounding.
table1 = doc.tables[1]
table1.rows[10].cells[4].text = "Pointwise variability only; no simultaneous coverage guarantee (post-hoc band check)"
table1.rows[11].cells[4].text = "80% acceptance target missed; post-hoc matched comparison shows no clear gain over correlation ranking"
for row_index in (10, 11):
    for paragraph in table1.rows[row_index].cells[4].paragraphs:
        for run in paragraph.runs: run.font.size = Pt(7.5)
assert "Random hours" in doc.tables[6].rows[2].cells[0].text
doc.tables[6].rows[2].cells[3].text = "0.022 / 0.022"

# Post-hoc results appear after the existing frozen E2 results, without renumbering frozen tables.
anchor = p[100]
new = doc.add_paragraph(style="Body")
new.add_run("Matched-acceptance ablation (post hoc). ").bold = True
new.add_run("Among 2,808 unmasked held-out cases, 247 failed A1 and 2,561 passed the common upstream eligibility conditions. Without A2, all 2,561 were accepted (91.2%; median error 0.059, p90 0.477). At the frozen 2,083-case acceptance count, stability rejection had median error 0.0462 and p90 0.2152; ranking the same eligible cases by the selected candidate's absolute IQD correlation gave 0.0460 and 0.2164. Station-month cluster 95% intervals for full minus correlation risk were −0.0018 to 0.0019 (median) and −0.0334 to 0.0320 (p90). In 1,000 random rejections matched to 2,083 cases, median error was 0.0590 and p90 0.4780; cluster intervals for full minus random risk were −0.0161 to −0.0099 and −0.4230 to −0.1442. Thus this benchmark supports rejection of poorer cases, but not an incremental advantage of stability over correlation ranking. The correlation cutoff (|r| = 0.9155) was determined on this holdout only for descriptive comparison and is not a frozen deployment rule (Table S1; Fig. S1).")
anchor._p.addnext(new._p)

caption = doc.add_paragraph(style="Body")
caption.add_run("Table S1. ").bold = True
caption.add_run("Post-hoc abstention ablation on the held-out unmasked E2 cases. Error is relative L2 error among accepted cases; matched arms accept 2,083 cases. The random arm reports the median over 1,000 random draws.")
new._p.addnext(caption._p)
table = doc.add_table(rows=1, cols=4)
table.style = "Table Grid"
for cell, label in zip(table.rows[0].cells, ("Rule", "Accepted / 2,808", "Median error", "p90 error")):
    cell.text = label
for values in (("Frozen stability", "2,083", "0.0462", "0.2152"),
               ("No A2, native", "2,561", "0.0590", "0.4766"),
               ("Correlation, matched", "2,083", "0.0460", "0.2164"),
               ("Random, matched", "2,083", "0.0590", "0.4780")):
    for cell, value in zip(table.add_row().cells, values): cell.text = value
caption._p.addnext(table._tbl)
for cell in table.rows[0].cells:
    for paragraph in cell.paragraphs:
        for run in paragraph.runs: run.bold = True
for row in table.rows:
    for cell in row.cells:
        for paragraph in cell.paragraphs:
            for run in paragraph.runs: run.font.size = Pt(8.5)

# Add the fully generated risk–acceptance source figure after the frozen Fig. 5 caption.
fig_anchor = p[103]
fig = doc.add_paragraph(style="Body")
fig.alignment = 1
fig.add_run().add_picture(str(FIGURE), width=Inches(5.9))
fig_anchor._p.addnext(fig._p)
figcap = doc.add_paragraph(style="Body")
figcap.add_run("Fig. S1. ").bold = True
figcap.add_run("Post-hoc median and 90th-percentile relative L2 error versus accepted fraction of 2,808 holdout cases. Stability and correlation rankings share the same 2,561 A1-eligible cases; random rejection is the mean of 100 draws per curve point. The pale vertical line marks frozen acceptance (74.18%); the dash-dot line marks the pre-specified 80% target. Matched operating-point uncertainty is reported in the text and per-case source data are archived with the code.")
fig._p.addnext(figcap._p)

doc.save(TARGET)
print(TARGET)
